def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            mask = tuple(tuple(int((x, y) in cells) for y in range(c0, c1 + 1))
                         for x in range(r0, r1 + 1))
            result.append({
                'color': color, 'cells': cells, 'mask': mask,
                'center': (sum(x for x, _ in cells) / len(cells),
                           sum(y for _, y in cells) / len(cells)),
                'box': (r0, c0, r1, c1),
            })
    return result


def _l_guides(components):
    guides = []
    for obj in components:
        cells = obj['cells']
        # An L-guide is exactly two contiguous perpendicular rays meeting at a corner.
        for cr, cc in cells:
            for vr in (-1, 1):
                for hc in (-1, 1):
                    vertical = {(r, cc) for r, c in cells if c == cc and (r - cr) * vr >= 0}
                    horizontal = {(cr, c) for r, c in cells if r == cr and (c - cc) * hc >= 0}
                    if not vertical or not horizontal or vertical | horizontal != cells:
                        continue
                    vdist = sorted(abs(r - cr) for r, _ in vertical)
                    hdist = sorted(abs(c - cc) for _, c in horizontal)
                    if (vdist == list(range(len(vdist))) and
                            hdist == list(range(len(hdist))) and
                            len(vdist) >= 3 and len(hdist) >= 3):
                        guides.append((obj, cr, cc, vr, hc))
    return guides


def transform(grid):
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    components = _components(grid, background)
    guides = _l_guides(components)
    groups = defaultdict(list)
    for obj in components:
        groups[obj['mask']].append(obj)

    candidates = []
    for guide, cr, cc, vr, hc in guides:
        for shape, objects in groups.items():
            if len(objects) < 2 or guide in objects:
                continue
            for source in objects:
                sr, sc = source['center']
                if (sr - cr) * vr <= 0 or (sc - cc) * hc <= 0:
                    continue
                for target in objects:
                    if target is source:
                        continue
                    tr, tc = target['center']
                    row_sign = 1 if tr > cr else -1 if tr < cr else 0
                    col_sign = 1 if tc > cc else -1 if tc < cc else 0
                    # The twin lies across one arm of the L, while staying on the
                    # same side of its other arm.
                    if ((row_sign == -vr and (tc - cc) * hc > 0) or
                            (col_sign == -hc and (tr - cr) * vr > 0)):
                        candidates.append((len(source['cells']), len(guide['cells']),
                                           target, guide['color']))
    if not candidates:
        return [row[:] for row in grid]

    # Larger repeated silhouettes provide the strongest geometric evidence; among
    # otherwise equal candidates prefer the longest guide.
    _, _, target, new_color = max(candidates, key=lambda item: (item[0], item[1]))
    out = [row[:] for row in grid]
    for r, c in target['cells']:
        out[r][c] = new_color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
