 "content": "from collections import Counter, defaultdict, deque


def _components(grid, background):
    """Return monochrome 4-connected foreground components."""
    height, width = len(grid), len(grid[0])
    seen = set()
    result = []

    for row in range(height):
        for col in range(width):
            color = grid[row][col]
            if color == background or (row, col) in seen:
                continue

            cells = set()
            queue = deque([(row, col)])
            seen.add((row, col))
            while queue:
                r, c = queue.popleft()
                cells.add((r, c))
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (0 <= nr < height and 0 <= nc < width
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        queue.append((nr, nc))

            min_row = min(r for r, _ in cells)
            min_col = min(c for _, c in cells)
            shape = tuple(sorted((r - min_row, c - min_col) for r, c in cells))
            result.append({
                "color": color,
                "cells": cells,
                "shape": shape,
                "center": (
                    sum(r for r, _ in cells) / len(cells),
                    sum(c for _, c in cells) / len(cells),
                ),
            })

    return result


def _find_l_guide(components):
    """Find the largest component made of two perpendicular, one-sided arms."""
    candidates = []
    for index, component in enumerate(components):
        cells = component["cells"]
        if len(cells) < 5:
            continue

        for elbow_row, elbow_col in cells:
            for row_direction in (-1, 1):
                vertical = {
                    (r, c) for r, c in cells
                    if c == elbow_col and (r - elbow_row) * row_direction >= 0
                }
                if len(vertical) < 3:
                    continue

                for col_direction in (-1, 1):
                    horizontal = {
                        (r, c) for r, c in cells
                        if r == elbow_row and (c - elbow_col) * col_direction >= 0
                    }
                    if len(horizontal) >= 3 and vertical | horizontal == cells:
                        candidates.append((
                            len(cells), index, elbow_row, elbow_col,
                            row_direction, col_direction,
                        ))

    if not candidates:
        return None

    _, index, elbow_row, elbow_col, row_direction, col_direction = max(candidates)
    return index, elbow_row, elbow_col, row_direction, col_direction


def _crossed_arms(first, second, guide_cells, elbow_row, elbow_col):
    """Return which finite L arms the segment between two object centers crosses."""
    row_a, col_a = first
    row_b, col_b = second
    horizontal_cols = [c for r, c in guide_cells if r == elbow_row]
    vertical_rows = [r for r, c in guide_cells if c == elbow_col]
    horizontal_bounds = (min(horizontal_cols), max(horizontal_cols))
    vertical_bounds = (min(vertical_rows), max(vertical_rows))
    crossed = []

    # Intersect with the horizontal arm (the line r = elbow_row).
    if row_a == row_b == elbow_row:
        if max(min(col_a, col_b), horizontal_bounds[0]) <= min(max(col_a, col_b), horizontal_bounds[1]):
            crossed.append("horizontal")
    elif (row_a - elbow_row) * (row_b - elbow_row) <= 0 and row_a != row_b:
        t = (elbow_row - row_a) / (row_b - row_a)
        crossing_col = col_a + t * (col_b - col_a)
        if horizontal_bounds[0] <= crossing_col <= horizontal_bounds[1]:
            crossed.append("horizontal")

    # Intersect with the vertical arm (the line c = elbow_col).
    if col_a == col_b == elbow_col:
        if max(min(row_a, row_b), vertical_bounds[0]) <= min(max(row_a, row_b), vertical_bounds[1]):
            crossed.append("vertical")
    elif (col_a - elbow_col) * (col_b - elbow_col) <= 0 and col_a != col_b:
        t = (elbow_col - col_a) / (col_b - col_a)
        crossing_row = row_a + t * (row_b - row_a)
        if vertical_bounds[0] <= crossing_row <= vertical_bounds[1]:
            crossed.append("vertical")

    return crossed


def transform(grid):
    """Recolor the directionally selected member of an identical-shape pair.

    A colored L is the guide. Find translated copies of the same connected
    shape whose center-to-center segment crosses one of the L's arms. The
    crossed arm determines the split: across a horizontal arm, select the
    object opposite the vertical arm; across a vertical arm, select the object
    opposite the horizontal arm. Recolor that object with the guide color.
    """
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    output = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    components = _components(grid, background)
    guide = _find_l_guide(components)
    if guide is None:
        return output

    guide_index, elbow_row, elbow_col, row_direction, col_direction = guide
    guide_cells = components[guide_index]["cells"]
    guide_color = components[guide_index]["color"]

    by_shape = defaultdict(list)
    for index, component in enumerate(components):
        if index != guide_index:
            by_shape[component["shape"]].append(index)

    candidates = []
    for indices in by_shape.values():
        for position, first_index in enumerate(indices):
            for second_index in indices[position + 1:]:
                first = components[first_index]
                second = components[second_index]
                crossed = _crossed_arms(
                    first["center"], second["center"], guide_cells,
                    elbow_row, elbow_col,
                )
                if not crossed:
                    continue

                first_row, first_col = first["center"]
                second_row, second_col = second["center"]
                first_dot = ((first_row - elbow_row) * row_direction
                             + (first_col - elbow_col) * col_direction)
                second_dot = ((second_row - elbow_row) * row_direction
                              + (second_col - elbow_col) * col_direction)

                if len(crossed) == 1 and crossed[0] == "horizontal":
                    first_side = (first_row - elbow_row) * row_direction
                    second_side = (second_row - elbow_row) * row_direction
                    chosen = first_index if first_side < second_side else second_index
                elif len(crossed) == 1 and crossed[0] == "vertical":
                    first_side = (first_col - elbow_col) * col_direction
                    second_side = (second_col - elbow_col) * col_direction
                    chosen = first_index if first_side < second_side else second_index
                else:
                    chosen = first_index if first_dot < second_dot else second_index

                size = len(first["cells"])
                candidates.append((size, first_dot + second_dot, chosen))

    if not candidates:
        return output

    # If multiple repeated motifs cross the guide, prefer the most substantial
    # one; the examples have a unique crossing pair at the winning size.
    _, _, chosen_index = max(candidates, key=lambda item: (item[0], -item[1]))
    for row, col in components[chosen_index]["cells"]:
        output[row][col] = guide_color
    return output


