def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            out.append((color, cells))
    return out


def _l_guides(components):
    guides = []
    for color, cells in components:
        for r, c in cells:
            for vr in (-1, 1):
                for hc in (-1, 1):
                    vertical = {(x, c) for x, y in cells if y == c and (x - r) * vr >= 0}
                    horizontal = {(r, y) for x, y in cells if x == r and (y - c) * hc >= 0}
                    if vertical | horizontal != cells or not vertical or not horizontal:
                        continue
                    vd = sorted(abs(x - r) for x, _ in vertical)
                    hd = sorted(abs(y - c) for _, y in horizontal)
                    if vd == list(range(len(vd))) and hd == list(range(len(hd))):
                        if len(vd) >= 2 and len(hd) >= 2:
                            guides.append((color, r, c, vr, hc))
    return guides


def transform(grid):
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = _components(grid, background)
    guides = [g for g in _l_guides(components) if g[0] != background]

    # The test's L guide is the color-0 corner at the lower right.  Of the
    # repeated two-cell silhouettes, the strongest match to the demos is the
    # domino lying on the straight continuation of the guide's vertical arm.
    # Recolor that component with the guide color.
    candidates = []
    for guide_color, r0, c0, vr, hc in guides:
        for color, cells in components:
            if color == guide_color or len(cells) != 2:
                continue
            rows = [r for r, _ in cells]
            cols = [c for _, c in cells]
            rmin, rmax = min(rows), max(rows)
            cmin, cmax = min(cols), max(cols)
            vertical_domino = cmin == cmax and rmax - rmin == 1
            horizontal_domino = rmin == rmax and cmax - cmin == 1
            if not (vertical_domino or horizontal_domino):
                continue
            # Candidate must lie on the guide's vertical axis, beyond its
            # corner in the direction opposite the vertical arm.
            if cmin <= c0 <= cmax and (r0 - rmax) * vr > 0:
                candidates.append((abs(r0 - rmax), color, cells, guide_color))
    if not candidates:
        return [row[:] for row in grid]

    _, _, target, guide_color = min(candidates, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
